// =====================================================================
//  CONFIG — this is the ONLY node you need to edit before each run.
// =====================================================================
return [{
  json: {
    // 1) What your next video is about. The AI writes hooks for THIS.
    topic: "my video topic is about how meditation can change your life and give you clarity in your 20s",

    // 2) Paste the full link of your Google Sheet (it needs tabs named "data" and "final result").
    googleSheetUrl: "https://docs.google.com/spreadsheets/d/1LxnAdLJVjYSc0UosFGZt60JivLWW2kUmjE_gtGdaFkk/edit",

    // 3) TikTok usernames to learn from (no @). Add or remove freely.
    profiles: [
      "Minolee.mp4", "mino1ee", "Briarcochran", "Katiexsocials", "Jun_yuh",
      "Iamjeanblack", "Joelroac", "Prosper_chiu", "Jayhoovy", "Jimrtang",
      "Ray_fu", "Nate.b.jones", "Dus_davis", "Higherupwellness", "T_nutrition_fitness",
      "Jacoboestreichercoaching", "Scotty.k.fitness", "Baxate_carter", "Andrewivx7.0",
      "Sajjaadkhader", "Your_finance_brother", "Chrisheynjr", "Daddywellness",
      "Ryan.magin", "Squidpakter", "Nomadatoast", "Calebboxxofficial", "Kanekallaway",
      "Askcatgpt", "Rpn", "Sebastienjefferies", "Sabrina_ramonov", "Benkaluza", "iamjadenly"
    ],

    // 4) Knobs (defaults are sensible)
    videosPerProfile: 2,        // latest N videos per profile (more = better data, higher Apify cost)
    maxAgeDays: 30,             // ignore videos older than this
    topPercent: 0.30,           // keep the top 30% by viral score
    maxVideosToTranscribe: 25,  // hard cap so a big run can't surprise you on cost
    hookSeconds: 7,             // how much of the start of each video counts as "the hook"
    hookCount: 10,              // how many new hooks to write
    model: "gpt-4.1-mini",      // OpenAI model that writes the hooks

    // Auto-filled: lets you tell runs apart in the sheet
    runId: new Date().toISOString()
  }
}];

// Cleans the Apify output, drops old/broken rows, scores each video, keeps the best.
const cfg = $('Config').first().json;
const now = Date.now();
const cutoff = now - cfg.maxAgeDays * 864e5;

const seen = new Set();
const videos = [];

for (const item of $input.all()) {
  const v = item.json || {};
  // Apify returns rows like { error: "..." } for profiles it can't find: skip them.
  if (!v.id || !v.webVideoUrl) continue;
  if (seen.has(String(v.id))) continue;
  seen.add(String(v.id));

  const createdMs = (Number(v.createTime) * 1000) || Date.parse(v.createTimeISO) || 0;
  if (!createdMs || createdMs < cutoff) continue;

  const views = Number(v.playCount) || 0;
  const followers = Number(v.authorMeta?.fans) || 0;
  const ageDays = Math.max((now - createdMs) / 864e5, 0.1);
  const viewsPerDay = views / ageDays;
  // Growth-adjusted score: rewards small accounts that pop, not just big accounts.
  const viralScore = viewsPerDay / Math.pow(Math.max(followers, 1), 0.35);

  videos.push({
    json: {
      author: v.authorMeta?.name ?? null,
      followers,
      videoUrl: v.webVideoUrl,
      caption: (v.text || '').trim(),
      views,
      likes: Number(v.diggCount) || 0,
      comments: Number(v.commentCount) || 0,
      shares: Number(v.shareCount) || 0,
      durationSec: v.videoMeta?.duration ?? null,
      postedAt: new Date(createdMs).toISOString(),
      ageDays: Number(ageDays.toFixed(2)),
      viewsPerDay: Math.round(viewsPerDay),
      viralScore: Number(viralScore.toFixed(2))
    }
  });
}

if (!videos.length) {
  throw new Error('Apify returned no usable videos. Check the Apify credential, the profile names, and maxAgeDays in the Config node.');
}

videos.sort((a, b) => b.json.viralScore - a.json.viralScore);
const keep = Math.min(Math.max(Math.ceil(videos.length * cfg.topPercent), 1), cfg.maxVideosToTranscribe);
return videos.slice(0, keep);

// Picks the downloadable media link out of each TikWM response.
// Prefers the actual video (has the creator's voice) over the "music" track
// (which is often a song, not speech). Falls back to music only if the video is too big for Whisper.
const videos = $('Score & Keep Top Videos').all();
const MAX_BYTES = 24 * 1024 * 1024; // Whisper upload limit is 25 MB
const out = [];
let skipped = 0;

$input.all().forEach((item, i) => {
  const r = item.json || {};
  const d = r.data || {};
  const tooBig = Number(d.size) > MAX_BYTES;
  let url = (!tooBig && d.play) || d.music || null;
  if (r.code !== 0 || !url || !videos[i]) { skipped++; return; }
  if (url.startsWith('/')) url = 'https://www.tikwm.com' + url;

  out.push({
    json: { ...videos[i].json, mediaUrl: url, mediaType: url === d.music ? 'audio' : 'video' },
    pairedItem: { item: i }
  });
});

if (!out.length) {
  throw new Error(`TikWM could not return media for any of the ${skipped} videos. It may be rate-limiting you; wait a few minutes and run again.`);
}
return out;

// Gives every downloaded file a proper name/extension so OpenAI accepts it,
// and re-attaches the video info. Failed downloads are dropped here.
const metas = $('Extract Media URL').all();
const out = [];

$input.all().forEach((item, i) => {
  const bin = item.binary?.data;
  const meta = metas[i]?.json;
  if (!bin || !meta) return;
  const isVideo = meta.mediaType === 'video';
  bin.fileName = `clip_${i + 1}.${isVideo ? 'mp4' : 'mp3'}`;
  bin.fileExtension = isVideo ? 'mp4' : 'mp3';
  bin.mimeType = isVideo ? 'video/mp4' : 'audio/mpeg';
  out.push({ json: meta, binary: { data: bin }, pairedItem: { item: i } });
});

if (!out.length) throw new Error('None of the TikTok media files could be downloaded.');
return out;

// Combines each transcript with its video info and cuts out the first N seconds = the hook.
const cfg = $('Config').first().json;
const metas = $('Name Media File').all();
const savedAt = new Date().toISOString();
const rows = [];

$input.all().forEach((item, i) => {
  const meta = metas[i]?.json;
  if (!meta) return;
  const w = item.json || {};
  const segs = Array.isArray(w.segments) ? w.segments : [];
  const hookSegs = segs.filter(s => Number(s.start) < cfg.hookSeconds);

  let hookTranscript = hookSegs.map(s => String(s.text || '').trim()).join(' ').trim();
  if (!hookTranscript && w.text) hookTranscript = String(w.text).split(/\s+/).slice(0, 20).join(' ');

  // Whisper tells us how likely each segment is to be "not speech" (music, silence).
  const noSpeech = hookSegs.length
    ? hookSegs.reduce((a, s) => a + (Number(s.no_speech_prob) || 0), 0) / hookSegs.length
    : 1;
  const spokenHook = hookTranscript.length > 0 && noSpeech < 0.5 ? 'yes' : 'no';

  rows.push({
    json: {
      runId: cfg.runId,
      author: meta.author,
      followers: meta.followers,
      videoUrl: meta.videoUrl,
      caption: meta.caption,
      views: meta.views,
      likes: meta.likes,
      comments: meta.comments,
      shares: meta.shares,
      durationSec: meta.durationSec,
      postedAt: meta.postedAt,
      viewsPerDay: meta.viewsPerDay,
      viralScore: meta.viralScore,
      hookTranscript,
      spokenHook,
      fullTranscript: String(w.text || '').slice(0, 2000),
      status: w.error ? 'transcription_failed' : 'ok',
      savedAt
    }
  });
});

if (!rows.length) throw new Error('No transcripts came back from OpenAI. Check the OpenAI credential and that your account has credit.');
return rows;

// Builds one request for the AI: learn from the winning hooks, then write new ones for your topic.
const cfg = $('Config').first().json;
const rows = $input.all().map(i => i.json).sort((a, b) => b.viralScore - a.viralScore);

const spoken = rows.filter(r => r.spokenHook === 'yes');
const textOnly = rows.filter(r => r.spokenHook !== 'yes' && r.caption);

const fmt = (r, n) => [
  `Example #${n} (viral score ${r.viralScore}, ${r.views.toLocaleString('en-US')} views, @${r.author}, ${r.followers.toLocaleString('en-US')} followers)`,
  `Spoken hook (first ${cfg.hookSeconds}s, auto-transcribed, may contain small errors): ${r.hookTranscript || '(none)'}`,
  `Caption: ${r.caption || '(none)'}`
].join('\n');

let n = 0;
const spokenBlock = spoken.map(r => fmt(r, ++n)).join('\n\n');
const textBlock = textOnly.map(r => fmt(r, ++n)).join('\n\n');

const system = `You are a world-class short-form video strategist and hook writer. A hook is the first 1-3 seconds of a TikTok/Reel/Short: the words spoken (and shown on screen) that stop the scroll.

You will be given real hooks from recent videos that statistically outperformed their creators' follower counts. Study them first: for each, infer the audience, the promise, the emotional trigger and the structure (bold claim, contrarian take, curiosity gap, specific number, "POV", direct callout, story-in-media-res, mistake/warning, etc.).

Data quality rules:
- Spoken hooks are automatic transcripts; fix obvious mishearings using the caption.
- If a "spoken hook" reads like song lyrics or nonsense, ignore its wording and learn only from its caption.
- Learn the PATTERNS. Never copy a hook word for word.

Output rules:
- Return ONLY valid JSON, no markdown, in exactly this shape:
{"hooks":[{"hook":"the words to say out loud","onScreenText":"short text overlay, max 8 words","pattern":"name of the pattern used","inspiredBy":"Example #N","whyItWorks":"one sentence"}]}`;

const user = `TRAINING DATA: ${rows.length} high-performing videos.

=== SPOKEN HOOKS (strongest signal) ===
${spokenBlock || '(none this run)'}

=== CAPTION-ONLY / MUSIC VIDEOS (weaker signal) ===
${textBlock || '(none this run)'}

=== YOUR TASK ===
Write exactly ${cfg.hookCount} new hooks for this video:
"${cfg.topic}"

Each hook must:
- grab attention in the first second and be speakable in under 3 seconds (roughly 6-15 words)
- use a pattern that clearly appears in the training data (mix several different patterns)
- be specific: concrete numbers, ages, timeframes or situations beat vague claims
- sound like a real person talking to camera, not an ad, and not like song lyrics
- be honest: no claims the video can't deliver on`;

return [{
  json: {
    exampleCount: rows.length,
    body: {
      model: cfg.model,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user }
      ]
    }
  }
}];

// Turns the AI's JSON answer into one row per hook for the "final result" tab.
const cfg = $('Config').first().json;
const res = $input.first().json;
const content = res.choices?.[0]?.message?.content || '';

let parsed;
try {
  parsed = JSON.parse(content.replace(/^```(?:json)?\s*|\s*```$/g, ''));
} catch (e) {
  throw new Error('The AI did not return valid JSON. First 500 characters: ' + content.slice(0, 500));
}

const hooks = Array.isArray(parsed.hooks) ? parsed.hooks : [];
if (!hooks.length) throw new Error('The AI returned no hooks: ' + content.slice(0, 500));

const examplesUsed = $('Build AI Prompt').first().json.exampleCount;
const createdAt = new Date().toISOString();

return hooks.map((h, i) => ({
  json: {
    runId: cfg.runId,
    topic: cfg.topic,
    rank: i + 1,
    hook: String(h.hook || '').trim(),
    onScreenText: String(h.onScreenText || '').trim(),
    pattern: String(h.pattern || '').trim(),
    inspiredBy: String(h.inspiredBy || '').trim(),
    whyItWorks: String(h.whyItWorks || '').trim(),
    examplesUsed,
    createdAt
  }
}));
